import { INTERVALS } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import styles from './BoxesDiagram.module.css';

/** How tall each box is drawn, low to high: a picture of waiting longer, not a measurement. */
const BOX_HEIGHTS = [26, 42, 58, 78, 100] as const;

/**
 * The Leitner schedule as a picture: five boxes, each waiting longer than
 * the last, with the days each one waits from the engine's own intervals.
 * Onboarding's "Here's how it works" and the "Five boxes" card of How Lexpad
 * works both draw it. The grid follows the reading direction, so in a
 * right-to-left layout box 1 is on the right.
 */
export function BoxesDiagram({ className }: { className?: string | undefined } = {}): React.JSX.Element {
  const interval = (days: number): string =>
    days === 0
      ? t('onboarding.intervalToday')
      : days === 1
        ? t('onboarding.intervalOneDay')
        : t('onboarding.intervalDays', { n: days });
  return (
    <figure className={cx(styles.diagram, className)} aria-label={t('onboarding.boxesTitle')}>
      <figcaption className={styles.diagramHead}>
        <span className={styles.diagramTitle}>{t('onboarding.boxesTitle')}</span>
        <span className={styles.diagramLead}>{t('onboarding.boxesLead')}</span>
      </figcaption>
      <div className={styles.bars}>
        {BOX_HEIGHTS.map((height, index) => (
          <div key={index} className={styles.barColumn}>
            <div
              className={styles.bar}
              style={{
                height: `${String(height)}%`,
                opacity: 0.4 + index * 0.15,
                animationDelay: `${String(index * 70)}ms`,
              }}
            />
            <span className={styles.barLabel}>{t('onboarding.box', { n: index + 1 })}</span>
            <span className={styles.barInterval}>{interval(INTERVALS[index] ?? 0)}</span>
          </div>
        ))}
      </div>
      <dl className={styles.legend}>
        <div className={styles.legendItem}>
          <dt className={styles.legendRight}>{t('onboarding.legendRight')}</dt>
          <dd>{t('onboarding.legendRightBody')}</dd>
        </div>
        <div className={styles.legendItem}>
          <dt className={styles.legendWrong}>{t('onboarding.legendWrong')}</dt>
          <dd>{t('onboarding.legendWrongBody')}</dd>
        </div>
        <div className={styles.legendItem}>
          <dt>{t('onboarding.legendMastered')}</dt>
          <dd>{t('onboarding.legendMasteredBody')}</dd>
        </div>
      </dl>
    </figure>
  );
}
